head.b:skin:
/*
 * EditorialVocab AdSense Pro Theme (Clean & Minimal Edition)
 * High Speed, Reader Friendly, 100% Policy-Safe
 */

:root {
  --bg-page: #f8fafc;
  --bg-card: #ffffff;
  --bg-subtle: #f1f5f9;
  --text-main: #0f172a;
  --text-body: #334155;
  --text-muted: #64748b;
  --text-light: #94a3b8;
  --border: #e2e8f0;
  --border-strong: #cbd5e1;

  --primary: #4f46e5;
  --primary-hover: #4338ca;
  --primary-subtle: #eef2ff;

  --font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-hindi: 'Hind', sans-serif;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 3px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 25px rgba(0,0,0,0.07);

  --max-width: 1200px;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  background-color: var(--bg-page);
  color: var(--text-body);
  font-family: var(--font-sans);
  line-height: 1.7;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--primary-hover);
  text-decoration: underline;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.ev-container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 20px;
  width: 100%;
}

/* Top Strip */
.ev-topbar {
  background-color: #0f172a;
  color: #cbd5e1;
  font-size: 12.5px;
  padding: 6px 0;
  border-bottom: 1px solid #1e293b;
}

.ev-topbar-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.ev-topbar-links {
  display: flex;
  gap: 16px;
}

.ev-topbar-links a {
  color: #94a3b8;
  font-size: 12px;
  font-weight: 600;
}

.ev-topbar-links a:hover {
  color: #ffffff;
  text-decoration: none;
}

/* Main Header */
.ev-header {
  background-color: #ffffff;
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

.ev-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 0;
  gap: 20px;
}

.ev-brand-group {
  display: flex;
  flex-direction: column;
}

.ev-brand-logo {
  font-size: 24px;
  font-weight: 900;
  color: var(--text-main);
  letter-spacing: -0.5px;
  line-height: 1.1;
}

.ev-brand-logo span {
  color: var(--primary);
}

.ev-brand-sub {
  font-size: 11.5px;
  color: var(--text-muted);
  font-weight: 500;
}

/* Clean Navigation Menu */
.ev-nav {
  display: flex;
  align-items: center;
  gap: 4px;
}

.ev-nav a {
  color: var(--text-body);
  font-size: 14px;
  font-weight: 700;
  padding: 7px 12px;
  border-radius: var(--radius-sm);
  transition: all 0.15s ease;
  white-space: nowrap;
}

.ev-nav a:hover {
  color: var(--primary);
  background-color: var(--primary-subtle);
  text-decoration: none;
}

.ev-search-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.ev-search-box {
  position: relative;
}

.ev-search-box input {
  background: var(--bg-page);
  border: 1px solid var(--border);
  padding: 7px 14px 7px 32px;
  border-radius: var(--radius-full);
  font-size: 13px;
  color: var(--text-main);
  outline: none;
  width: 170px;
  transition: all 0.2s;
}

.ev-search-box input:focus {
  width: 220px;
  border-color: var(--primary);
  background: #ffffff;
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
}

.ev-search-box span {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-light);
  font-size: 12px;
  pointer-events: none;
}

.ev-mob-btn {
  display: none;
  background: none;
  border: 1px solid var(--border);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: 18px;
  color: var(--text-main);
}

/* Layout Grid */
.ev-main-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 30px;
  margin: 28px auto 50px auto;
}

.ev-main-col {
  min-width: 0;
}

.ev-sidebar-col {
  min-width: 0;
}

/* Homepage Welcome Card */
.ev-hero-box {
  background: linear-gradient(135deg, #1e1b4b 0%, #312e81 60%, #0f172a 100%);
  color: #ffffff;
  padding: 28px 30px;
  border-radius: var(--radius-lg);
  margin-bottom: 26px;
  box-shadow: var(--shadow-md);
}

.ev-hero-tag {
  display: inline-block;
  background: rgba(255,255,255,0.15);
  color: #e0e7ff;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  padding: 3px 10px;
  border-radius: var(--radius-full);
  letter-spacing: 0.8px;
  margin-bottom: 10px;
}

.ev-hero-title {
  font-size: clamp(20px, 3.5vw, 28px);
  font-weight: 900;
  line-height: 1.25;
  margin-bottom: 8px;
  color: #ffffff;
}

.ev-hero-text {
  font-size: 14.5px;
  color: #cbd5e1;
  max-width: 650px;
  line-height: 1.6;
  margin-bottom: 16px;
}

.ev-hero-links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.ev-hero-btn {
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #ffffff;
  padding: 5px 12px;
  border-radius: var(--radius-full);
  font-size: 12px;
  font-weight: 700;
}

.ev-hero-btn:hover {
  background: #ffffff;
  color: #0f172a;
  text-decoration: none;
}

/* Section Bar */
.ev-sec-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 2px solid var(--border);
  padding-bottom: 10px;
  margin-bottom: 20px;
}

.ev-sec-title {
  font-size: 19px;
  font-weight: 900;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 8px;
}

.ev-sec-title::before {
  content: '';
  display: block;
  width: 4px;
  height: 18px;
  background: var(--primary);
  border-radius: var(--radius-full);
}

/* Feed Post Cards */
.ev-feed {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.ev-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s, box-shadow 0.2s;
  display: flex;
  flex-direction: column;
}

.ev-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
  border-color: var(--border-strong);
}

.ev-card-thumb {
  width: 100%;
  max-height: 220px;
  object-fit: cover;
  border-bottom: 1px solid var(--border);
}

.ev-card-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.ev-card-tags {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  color: var(--text-muted);
  margin-bottom: 8px;
  flex-wrap: wrap;
}

.ev-card-source-tag {
  background: var(--primary-subtle);
  color: var(--primary);
  font-weight: 800;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  font-size: 11px;
  text-transform: uppercase;
}

.ev-card-h2 {
  font-size: 19px;
  font-weight: 800;
  line-height: 1.35;
  color: var(--text-main);
  margin-bottom: 8px;
}

.ev-card-h2 a {
  color: var(--text-main);
}

.ev-card-h2 a:hover {
  color: var(--primary);
  text-decoration: none;
}

.ev-card-desc {
  font-size: 14px;
  color: var(--text-body);
  line-height: 1.6;
  margin-bottom: 14px;
  flex: 1;
}

.ev-card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid var(--border);
  padding-top: 12px;
  font-size: 13px;
  font-weight: 700;
}

.ev-card-read {
  color: var(--primary);
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

/* Single Post Container */
.ev-post-box {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: clamp(20px, 4vw, 34px);
  box-shadow: var(--shadow-sm);
}

.ev-crumbs {
  font-size: 13px;
  color: var(--text-muted);
  margin-bottom: 14px;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.ev-crumbs a {
  color: var(--text-muted);
}

.ev-crumbs a:hover {
  color: var(--primary);
}

.ev-post-h1 {
  font-size: clamp(23px, 4vw, 32px);
  font-weight: 900;
  color: var(--text-main);
  line-height: 1.25;
  margin-bottom: 12px;
}

.ev-post-meta {
  display: flex;
  align-items: center;
  gap: 14px;
  font-size: 13px;
  color: var(--text-muted);
  padding-bottom: 18px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 22px;
  flex-wrap: wrap;
}

.ev-content {
  font-size: 16px;
  line-height: 1.75;
  color: var(--text-main);
}

.ev-content p {
  margin-bottom: 16px;
}

.ev-content h2 {
  font-size: 21px;
  font-weight: 800;
  color: var(--text-main);
  margin: 26px 0 12px 0;
  line-height: 1.3;
}

.ev-content h3 {
  font-size: 17px;
  font-weight: 800;
  color: var(--text-main);
  margin: 20px 0 10px 0;
}

/* Share Bar */
.ev-share {
  margin: 28px 0;
  padding: 14px 18px;
  background: var(--bg-subtle);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
}

.ev-share span {
  font-size: 12.5px;
  font-weight: 800;
  color: var(--text-main);
  text-transform: uppercase;
}

.ev-share-links {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.ev-share-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  font-weight: 700;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  color: #ffffff;
  text-decoration: none;
}

.ev-share-btn:hover {
  opacity: 0.9;
  color: #ffffff;
  text-decoration: none;
}

.ev-s-wa { background: #25d366; }
.ev-s-tg { background: #0088cc; }
.ev-s-tw { background: #000000; }

/* Static Pages */
.ev-page-box {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: clamp(24px, 4vw, 40px);
  box-shadow: var(--shadow-sm);
}

.ev-page-h1 {
  font-size: clamp(24px, 4vw, 32px);
  font-weight: 900;
  color: var(--text-main);
  margin-bottom: 16px;
  border-bottom: 2px solid var(--border);
  padding-bottom: 12px;
}

/* 404 / ERROR / EMPTY STATE HANDLER */
.ev-notice-box {
  background: #ffffff;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: clamp(30px, 5vw, 50px) 20px;
  text-align: center;
  box-shadow: var(--shadow-md);
  margin: 10px auto;
}

.ev-notice-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 70px;
  height: 70px;
  border-radius: 50%;
  background: #fee2e2;
  color: #ef4444;
  font-size: 32px;
  margin-bottom: 16px;
}

.ev-notice-icon.info {
  background: var(--primary-subtle);
  color: var(--primary);
}

.ev-notice-code {
  font-size: clamp(42px, 7vw, 72px);
  font-weight: 900;
  color: var(--text-main);
  line-height: 1;
  margin-bottom: 8px;
}

.ev-notice-h2 {
  font-size: clamp(19px, 3.5vw, 24px);
  font-weight: 800;
  color: var(--text-main);
  margin-bottom: 10px;
}

.ev-notice-p {
  font-size: 14.5px;
  color: var(--text-muted);
  max-width: 520px;
  margin: 0 auto 20px auto;
  line-height: 1.6;
}

.ev-notice-form {
  max-width: 440px;
  margin: 0 auto 22px auto;
  display: flex;
  gap: 8px;
}

.ev-notice-form input {
  flex: 1;
  padding: 11px 16px;
  border: 2px solid var(--border);
  border-radius: var(--radius-md);
  font-size: 14px;
  outline: none;
}

.ev-notice-form input:focus {
  border-color: var(--primary);
}

.ev-notice-form button {
  background: var(--primary);
  color: #ffffff;
  border: none;
  padding: 11px 20px;
  border-radius: var(--radius-md);
  font-weight: 800;
  font-size: 14px;
  cursor: pointer;
}

.ev-notice-btns {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
}

.ev-btn-pill {
  background: var(--bg-subtle);
  color: var(--text-main);
  border: 1px solid var(--border);
  padding: 8px 16px;
  border-radius: var(--radius-full);
  font-size: 12.5px;
  font-weight: 700;
}

.ev-btn-pill:hover {
  background: var(--primary);
  color: #ffffff;
  border-color: var(--primary);
  text-decoration: none;
}

.ev-btn-pill.primary {
  background: var(--primary);
  color: #ffffff;
  border-color: var(--primary);
}

/* Sidebar Widgets */
.ev-sidebar-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px;
  margin-bottom: 20px;
  box-shadow: var(--shadow-sm);
}

.ev-sidebar-title {
  font-size: 15px;
  font-weight: 900;
  color: var(--text-main);
  border-bottom: 2px solid var(--border);
  padding-bottom: 8px;
  margin-bottom: 14px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.ev-sidebar-title::before {
  content: '';
  display: block;
  width: 4px;
  height: 14px;
  background: var(--primary);
  border-radius: var(--radius-full);
}

.ev-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.ev-tag {
  background: var(--bg-subtle);
  border: 1px solid var(--border);
  color: var(--text-body);
  font-size: 12px;
  font-weight: 700;
  padding: 5px 10px;
  border-radius: var(--radius-full);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.ev-tag:hover {
  background: var(--primary-subtle);
  color: var(--primary);
  border-color: var(--primary);
  text-decoration: none;
}

.ev-tag-count {
  background: var(--border-strong);
  color: var(--text-main);
  font-size: 10px;
  padding: 1px 5px;
  border-radius: var(--radius-full);
  font-weight: 800;
}

/* Pagination */
.ev-pager {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: 26px 0;
  gap: 10px;
}

.ev-pager-btn {
  background: var(--bg-card);
  border: 1.5px solid var(--border);
  color: var(--text-main);
  font-size: 13.5px;
  font-weight: 800;
  padding: 9px 18px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.ev-pager-btn:hover {
  background: var(--primary);
  color: #ffffff;
  border-color: var(--primary);
  text-decoration: none;
}

/* Footer */
.ev-footer {
  background: #0f172a;
  color: #cbd5e1;
  margin-top: auto;
  border-top: 1px solid #1e293b;
  padding: 44px 0 20px 0;
}

.ev-footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 30px;
  margin-bottom: 34px;
}

.ev-footer-logo {
  font-size: 20px;
  font-weight: 900;
  color: #ffffff;
  margin-bottom: 10px;
}

.ev-footer-logo span {
  color: #818cf8;
}

.ev-footer-desc {
  font-size: 13px;
  line-height: 1.6;
  color: #94a3b8;
  max-width: 300px;
}

.ev-footer-h4 {
  font-size: 13.5px;
  font-weight: 800;
  color: #ffffff;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  margin-bottom: 14px;
  border-bottom: 1px solid #334155;
  padding-bottom: 6px;
}

.ev-footer-menu {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ev-footer-menu a {
  color: #94a3b8;
  font-size: 13px;
  font-weight: 600;
}

.ev-footer-menu a:hover {
  color: #ffffff;
  text-decoration: underline;
}

.ev-footer-bot {
  border-top: 1px solid #1e293b;
  padding-top: 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 12px;
  color: #64748b;
}

.ev-footer-bot a {
  color: #94a3b8;
}

.ev-footer-bot a:hover {
  color: #ffffff;
}

/* Print Styles */
@media print {
  .ev-topbar, .ev-header, .ev-footer, .ev-sidebar-col,
  .ev-share, .ev-pager, .ev-crumbs, #comments, .comments,
  #ev-toc-bar, #ev-pdf-section, #ev-quiz-section, #evQBox, .evNav, .evScorecard, button {
    display: none !important;
  }

  body, .ev-main-grid, .ev-main-col {
    background: #ffffff !important;
    color: #0f172a !important;
    margin: 0 !important;
    padding: 0 !important;
    display: block !important;
    max-width: 100% !important;
  }

  .ev-post-box {
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
  }

  .ev-card, #ev-vocab-section > div, #ev-idioms-section, #ev-idioms-section > div > div, .ev-print-quiz {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
    border: 1px solid #cbd5e1 !important;
    background: #ffffff !important;
    box-shadow: none !important;
    margin-bottom: 12px !important;
  }

  .ev-print-quiz {
    display: block !important;
  }
}

/* Responsive */
@media (max-width: 960px) {
  .ev-main-grid {
    grid-template-columns: 1fr;
  }

  .ev-footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .ev-nav {
    display: none;
  }

  .ev-mob-btn {
    display: block;
  }

  .ev-nav.active {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: #ffffff;
    border-bottom: 1px solid var(--border);
    padding: 14px 20px;
    box-shadow: var(--shadow-md);
  }
}

@media (max-width: 600px) {
  .ev-footer-grid {
    grid-template-columns: 1fr;
  }

  .ev-topbar-links {
    display: none;
  }

  .ev-search-box input {
    width: 130px;
  }

  .ev-search-box input:focus {
    width: 170px;
  }
}
